86	async function syncDiscordRoles(discordUid: string) {
87	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
88	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
89	
90	    console.log(`[Discord Bot] Attempting to sync roles for discord_uid: ${discordUid}`);
91	
92	    if (!apiUrl || !token) {
93	        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord role sync.');
94	        return; // Don't throw error, just log and skip sync
95	    }
96	    
97	    try {
98	        const res = await fetch(`${apiUrl}/api/roles/sync`, {
99	            method: 'POST',
100	            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
101	            body: JSON.stringify({ discord_uid: discordUid }),
102	            cache: 'no-store',
103	        });
104	         if (!res.ok) {
105	            const errorText = await res.text();
106	            console.error(`[Discord Bot] Failed to sync roles for ${discordUid}. Status: ${res.status}, Body: ${errorText}`);
107	        } else {
108	            console.log(`[Discord Bot] Successfully initiated role sync for discord_uid: ${discordUid}`);
109	        }
110	    } catch (e) {
111	        console.error(`[Discord Bot] Error during role sync for ${discordUid}:`, e);
112	    }
113	}
