149	export async function getMemberDisplayName(discordUid: string): Promise<string | null> {
150	    // 認証チェック
151	    const supabase = await createClient();
152	    const { data: { user } } = await supabase.auth.getUser();
153	    if (!user) return null;
154	
155	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
156	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
157	
158	    if (!apiUrl || !token || !discordUid) {
159	        console.error(`[Discord Bot] Cannot get display name. API URL, Token, or Discord UID is missing.`);
160	        return null;
161	    }
162	
163	    try {
164	        const response = await fetch(`${apiUrl}/api/nickname?discord_uid=${discordUid}`, {
165	            headers: {
166	                'Authorization': `Bearer ${token}`,
167	            },
168	            cache: 'no-store',
169	        });
170	
171	        if (!response.ok) {
172	            const errorText = await response.text();
173	            console.error(`[Discord Bot] Failed to fetch nickname for ${discordUid}: Status ${response.status}, Body: ${errorText}`);
174	            return null;
175	        }
176	        
177	        const data = await response.json();
178	        return data.name_only || null;
179	    } catch (error) {
180	        console.error(`[Discord Bot] Error fetching nickname for ${discordUid}:`, error);
181	        return null;
182	    }
183	}
