330	export async function resyncDiscordMember(values: z.infer<typeof reSyncSchema>) {
331	    const supabase = await createClient();
332	    const supabaseAdmin = await createAdminClient();
333	    const { data: { user } } = await supabase.auth.getUser();
334	
335	    if (!user) {
336	        return { error: '再連携するにはログインする必要があります。' };
337	    }
338	
339	    const parsedData = reSyncSchema.safeParse(values);
340	    if (!parsedData.success) {
341	        const firstError = parsedData.error.flatten().fieldErrors;
342	        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
343	        return { error: errorMessage };
344	    }
345	
346	    const { last_name, first_name } = parsedData.data;
347	    const fullName = (last_name + first_name).replace(/\s/g, '');
348	    const discordUid = user.user_metadata.provider_id;
349	
350	    if (!discordUid) {
351	        return { error: 'Discord UIDが取得できませんでした。' };
352	    }
353	
354	    // Check if member profile exists
355	    const { data: memberProfile } = await supabase
356	        .from('members')
357	        .select('*')
358	        .eq('supabase_auth_user_id', user.id)
359	        .is('deleted_at', null)
360	        .single();
361	
362	    if (!memberProfile) {
363	        return { error: 'メンバー情報が見つかりません。新規登録が必要です。' };
364	    }
365	    
366	    // Update user_metadata with name
367	    const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
368	        user.id,
369	        { user_metadata: { ...user.user_metadata, last_name, first_name, name: fullName } }
370	    );
371	     if (userUpdateError) {
372	        console.error('Error updating user metadata during resync:', userUpdateError);
373	        return { error: 'ユーザー情報の更新に失敗しました。' };
374	    }
375	
376	    // Re-sync Discord nickname and roles
377	    await syncDiscordNickname(discordUid, fullName);
378	    await syncDiscordRoles(discordUid);
379	
380	    revalidatePath('/dashboard', 'layout');
381	    return { error: null };
382	}
