385	export async function updateMyProfile(values: z.infer<typeof profileUpdateSchema>) {
386	    const supabase = await createClient();
387	    const supabaseAdmin = await createAdminClient();
388	    const { data: { user } } = await supabase.auth.getUser();
389	
390	    if (!user) {
391	        return { error: 'プロフィールを更新するにはログインする必要があります。' };
392	    }
393	
394	    const parsedData = profileUpdateSchema.safeParse(values);
395	    if (!parsedData.success) {
396	        return { error: '無効なデータが提供されました。' };
397	    }
398	
399	    const { student_number } = parsedData.data;
400	
401	    const { error } = await supabaseAdmin
402	        .from('members')
403	        .update({ student_number })
404	        .eq('supabase_auth_user_id', user.id);
405	
406	    if (error) {
407	        console.error('Error updating profile:', error);
408	        return { error: 'プロフィールの更新に失敗しました。もう一度お試しください。' };
409	    }
410	
411	    const { data: member } = await supabase.from("members").select("discord_uid").eq("supabase_auth_user_id", user.id).single();
412	    if (member) {
413	        const realName = await getMemberDisplayName(member.discord_uid);
414	        if (realName) await syncDiscordNickname(member.discord_uid, realName);
415	        await syncDiscordRoles(member.discord_uid);
416	    }
417	
418	    revalidatePath('/dashboard', 'layout');
419	    revalidatePath('/dashboard/admin/members');
420	    return { error: null };
421	}
