423	export async function updateMemberAdmin(userId: string, values: z.infer<typeof profileAdminUpdateSchema>) {
424	    try {
425	        await checkAdmin();
426	        const supabase = await createClient();
427	        const supabaseAdmin = await createAdminClient();
428	
429	        const parsedData = profileAdminUpdateSchema.safeParse(values);
430	        if (!parsedData.success) {
431	            console.error("Invalid admin update data:", parsedData.error.flatten());
432	            const firstError = parsedData.error.flatten().fieldErrors;
433	            const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
434	            return { error: errorMessage };
435	        }
436	
437	        const { last_name, first_name, generation, student_number, status, team_ids } = parsedData.data;
438	
439	        // 1. Update user metadata (name)
440	        const fullName = (last_name + first_name).replace(/\s/g, '');
441	        const { data: userToUpdate, error: getUserError } = await supabaseAdmin.auth.admin.getUserById(userId);
442	        if (getUserError) throw new Error(`ユーザー情報の取得に失敗: ${getUserError.message}`);
443	
444	        const { error: userUpdateError } = await supabaseAdmin.auth.admin.updateUserById(
445	            userId,
446	            { user_metadata: { ...userToUpdate.user.user_metadata, last_name, first_name, name: fullName } }
447	        );
448	        if (userUpdateError) throw new Error(`ユーザーメタデータの更新に失敗: ${userUpdateError.message}`);
449	
450	        // 2. Update member table (generation, status, student_number)
451	        await ensureGenerationRoleExists(generation);
452	        const { error: memberUpdateError } = await supabase
453	            .from('members')
454	            .update({ generation, student_number, status })
455	            .eq('supabase_auth_user_id', userId);
456	        if (memberUpdateError) throw new Error(`メンバーテーブルの更新に失敗: ${memberUpdateError.message}`);
457	        
458	        // 3. Update team relations
459	        const { error: deleteTeamsError } = await supabase
460	            .from('member_team_relations')
461	            .delete()
462	            .eq('member_id', userId);
463	        if (deleteTeamsError) throw new Error(`所属班の削除に失敗: ${deleteTeamsError.message}`);
464	
465	        if (team_ids && team_ids.length > 0) {
466	            const newRelations = team_ids.map(team_id => ({
467	                member_id: userId,
468	                team_id: team_id,
469	            }));
470	            const { error: insertTeamsError } = await supabase.from('member_team_relations').insert(newRelations);
471	            if (insertTeamsError) throw new Error(`所属班の更新に失敗: ${insertTeamsError.message}`);
472	        }
473	
474	        // 4. Sync with Discord
475	        await syncDiscordNickname(userToUpdate.user.user_metadata.provider_id, fullName);
476	        await syncDiscordRoles(userToUpdate.user.user_metadata.provider_id);
477	
478	        revalidatePath('/dashboard/admin/members');
479	        return { error: null };
480	    } catch (e: any) {
481	        console.error('Error updating member by admin:', e);
482	        return { error: e.message };
483	    }
484	}
