492	export async function toggleAdminStatus(userId: string, currentStatus: boolean) {
493	    const parsed = toggleAdminSchema.safeParse({ userId, currentStatus });
494	    if (!parsed.success) return { error: '無効なパラメータです。' };
495	
496	    const supabase = await createClient();
497	    const { data: { user } } = await supabase.auth.getUser();
498	
499	    if (!user) {
500	        return { error: '認証が必要です。' };
501	    }
502	
503	    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
504	    if (!admin?.is_admin) {
505	        return { error: '管理者権限が必要です。' };
506	    }
507	
508	     if (user.id === userId) {
509	        return { error: "自身の管理者ステータスは変更できません。" };
510	    }
511	
512	    const { error } = await supabase
513	        .from('members')
514	        .update({ is_admin: !currentStatus })
515	        .eq('supabase_auth_user_id', userId);
516	    
517	    if (error) {
518	        return { error: '管理者ステータスの更新に失敗しました。' };
519	    }
520	
521	    revalidatePath('/dashboard/admin/members');
522	    return { error: null };
523	}
