529	export async function deleteMember(userId: string) {
530	    const parsed = deleteMemberSchema.safeParse({ userId });
531	    if (!parsed.success) return { error: '無効なユーザーIDです。' };
532	
533	    const supabase = await createClient();
534	    const { data: { user } } = await supabase.auth.getUser();
